def create_default_approval_rule(apps, schema_editor):
    database = schema_editor.connection.alias
    Rule = apps.get_model('invoices', 'InvoiceApprovalRule')
    Step = apps.get_model('invoices', 'InvoiceApprovalStep')
    Invoice = apps.get_model('invoices', 'Invoice')
    rule, _ = Rule.objects.using(database).get_or_create(
        name='Default AP approval',
        defaults={
            'minimum_amount': 0,
            'maximum_amount': None,
            'approver_roles': ['Approver'],
            'reminder_after_hours': 24,
            'escalation_after_hours': 72,
            'active': True,
        },
    )
    for invoice in Invoice.objects.using(database).filter(
        status='PENDING_APPROVAL'
    ).iterator():
        for role in rule.approver_roles:
            Step.objects.using(database).get_or_create(
                invoice_id=invoice.pk,
                role=role,
                defaults={
                    'reminder_after_hours': rule.reminder_after_hours,
                    'escalation_after_hours': rule.escalation_after_hours,
                },
            )


